head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거)
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.fireDbClick = function(node) {
	var evt = document.createEvent('MouseEvents');
	evt.initEvent('dblclick', true, false);
	node.dispatchEvent(evt);
};
scwin.Dbclick = function(id) {
	var el = scwin.__getDom($p.id + id);
	scwin.fireDbClick(el);
};
scwin.checkValue = function(id, value) {
	return scwin.__getDom($p.id + id).textContent == value;
};
scwin.onpageload = function() {
	grid1.setRef({
		ref: "vector",
		baseNode: "vector",
		repeatNode: "data"
	});
	grid1.insertRow();
	// 0번 Column: 속성(maxlength="7.2"), 1번: setCellInputType options, 2번: setCellMaxLength API
	grid1.setCellInputType(0, 1, {
		inputType: "text",
		options: {
			dataType: "float",
			maxlength: "7.2",
			displayFormat: "#,###.#0",
			applyFormat: "all"
		}
	});
	grid1.setCellInputType(0, 2, {
		inputType: "text",
		options: {
			dataType: "float",
			applyFormat: "all"
		}
	});
	grid1.setCellMaxLength(0, 2, "7.2");
	grid1.setCellDisplayFormat(0, 2, "#,###.#0");
};
